$run=$pdo->query("SELECT id,dataset_id,run_name,baseline_mode,status,completed_at FROM evaluation_runs WHERE status='completed' ORDER BY id DESC LIMIT 1")->fetch(PDO::FETCH_ASSOC);
$results=$run?eval_run_summary($pdo,(int)$run['id']):null;
?>
