<section class="panel"><h2>Side-by-side results</h2><div class="scroll"><table><thead><tr><th>Metric</th><th>Traditional baseline</th><th>Proposed system</th></tr></thead><tbody><?php foreach(['accuracy'=>'Accuracy','macro_precision'=>'Macro precision','macro_recall'=>'Macro recall','macro_f1'=>'Macro F1','average_ms'=>'Average processing time (ms)','records_processed'=>'Records processed'] as $k=>$label):?><tr><td><?=h($label)?></td><td><?=number_format($results['traditional'][$k],2)?></td><td><?=number_format($results['proposed'][$k],2)?></td></tr><?php endforeach?></tbody></table></div><p class="muted">A higher classification metric is better; lower processing time is faster. A result is not automatically statistically significant.</p></section><?php endif?></main></body></html>